// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.text;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Random;

import org.junit.jupiter.api.Test;

class LiteralTextSummaryTest {

	@Test
	void persistentFingerprintMatchesKnownMurmurHash3X64Vectors() {
		assertThat(ByteBuffer.wrap(summarize("", Locale.ROOT)).getLong(16)).isZero();
		assertThat(ByteBuffer.wrap(summarize("hello", Locale.ROOT)).getLong(16)).isEqualTo(0xcbd8a7b341bd9b02L);
		assertThat(ByteBuffer.wrap(summarize("foo", Locale.ROOT)).getLong(16)).isEqualTo(0xe271865701f54561L);
	}

	@Test
	void fullLabelHashRejectsEqualLengthLabelsSharingTheEntireStoredPrefix() {
		byte[] summary = summarize("ABCDEFGH-one", Locale.ROOT);
		assertThat(summary).hasSize(LiteralTextSummary.BYTES);
		assertThat(query(LiteralTextSummary.Operation.EQUALS, "abcdefgh-one").mayMatch(summary, 0)).isTrue();
		assertThat(query(LiteralTextSummary.Operation.EQUALS, "abcdefgh-two").mayMatch(summary, 0)).isFalse();
		assertThat(query(LiteralTextSummary.Operation.EQUALS, "abcdefgh-on").mayMatch(summary, 0)).isFalse();
	}

	@Test
	void prefixPaddingDoesNotRejectAProperShortPrefixOrEmbeddedNul() {
		byte[] summary = summarize("A\u0000B\u0000CDEFGHI", Locale.ROOT);
		for (String prefix : List.of("", "a", "a\u0000", "a\u0000b", "a\u0000b\u0000cdefghi")) {
			assertThat(query(LiteralTextSummary.Operation.STARTS_WITH, prefix).mayMatch(summary, 0))
					.as("prefix %s", prefix)
					.isTrue();
		}
		assertThat(query(LiteralTextSummary.Operation.STARTS_WITH, "a\u0000c").mayMatch(summary, 0)).isFalse();
		assertThat(query(LiteralTextSummary.Operation.STARTS_WITH, "a\u0000b\u0000cdefghij").mayMatch(summary, 0))
				.isFalse();
	}

	@Test
	void rawUtf8PrefixMayEndInsideAMultibyteCharacter() {
		String label = "ABCDEFG\ud83d\ude00-\u00c5";
		byte[] summary = summarize(label, Locale.ROOT);
		for (String prefix : List.of("abcdefg", "abcdefg\ud83d\ude00", "abcdefg\ud83d\ude00-\u00e5")) {
			assertThat(query(LiteralTextSummary.Operation.STARTS_WITH, prefix).mayMatch(summary, 0)).isTrue();
		}
		assertThat(query(LiteralTextSummary.Operation.STARTS_WITH, "abcdefx").mayMatch(summary, 0)).isFalse();
	}

	@Test
	void longerPrefixesUseGramsAfterTheStoredLeadingBytes() {
		byte[] summary = summarize("ABCDEFGH ordinary catalog", Locale.ROOT);
		LiteralTextSummary.Query missing = query(LiteralTextSummary.Operation.STARTS_WITH, "abcdefgh xylophone");
		assertThat(missing.mayMatch(summary, 0)).isFalse();
		assertThat(missing.mayMatch(ByteBuffer.wrap(summary), 0)).isFalse();
		assertThat(query(LiteralTextSummary.Operation.STARTS_WITH, "abcdefgh ordinary").mayMatch(summary, 0)).isTrue();
	}

	@Test
	void containsUsesAllOverlappingByteGramsAndRetainsShortNeedles() {
		byte[] summary = summarize("FIRST Needle LAST", Locale.ROOT);
		for (String needle : List.of("", "n", "ne", "nee", "needle", "t needle l", "last")) {
			assertThat(query(LiteralTextSummary.Operation.CONTAINS, needle).mayMatch(summary, 0))
					.as("needle %s", needle)
					.isTrue();
		}
		assertThat(query(LiteralTextSummary.Operation.CONTAINS, "xylophone").mayMatch(summary, 0)).isFalse();
		assertThat(query(LiteralTextSummary.Operation.CONTAINS, "first needle last plus").mayMatch(summary, 0))
				.isFalse();
	}

	@Test
	void repeatedGramsDoNotRequireMultipleOccurrencesInTheSignature() {
		byte[] summary = summarize("baaaaaaaac", Locale.ROOT);
		assertThat(query(LiteralTextSummary.Operation.CONTAINS, "aaaaaaaa").mayMatch(summary, 0)).isTrue();
		assertThat(query(LiteralTextSummary.Operation.CONTAINS, "aaa").mayMatch(summary, 0)).isTrue();
		assertThat(query(LiteralTextSummary.Operation.CONTAINS, "zzz").mayMatch(summary, 0)).isFalse();
	}

	@Test
	void normalizationUsesTheCompleteLabelAndExplicitLocale() {
		List<String> labels = List.of("\u039f\u03a3", "A\u03a3A", "\u0130I\u0131i", "I\u0301J\u0301",
				"\u00c5\u00d8\u00c6\u00c9", "\ud801\udc00\ud801\udc01", "\u00dfSS", "A\u030a");
		for (Locale locale : List.of(Locale.ROOT, Locale.forLanguageTag("tr"), Locale.forLanguageTag("lt"))) {
			for (String label : labels) {
				String normalized = label.toLowerCase(locale);
				byte[] summary = summarize(label, locale);
				assertThat(LiteralTextSummary.prepare(LiteralTextSummary.Operation.EQUALS, normalized, locale)
						.mayMatch(summary, 0)).as("locale %s, label %s", locale, label).isTrue();
				assertEverySubstringSurvives(summary, normalized, locale);
			}
		}
	}

	@Test
	void preparedNeedleIsAlreadyEvaluatedUnlessLowercasingIsExplicitlyRequested() {
		byte[] summary = summarize("ABCDEFGHI", Locale.ROOT);
		assertThat(query(LiteralTextSummary.Operation.EQUALS, "ABCDEFGHI").mayMatch(summary, 0)).isFalse();
		assertThat(LiteralTextSummary.prepareLowercased(LiteralTextSummary.Operation.EQUALS, "ABCDEFGHI", Locale.ROOT)
				.mayMatch(summary, 0)).isTrue();
		assertThat(query(LiteralTextSummary.Operation.EQUALS, "abcdefghi").locale()).isEqualTo(Locale.ROOT);
	}

	@Test
	void malformedSurrogateNeedlesAlwaysPassThroughWithoutLexicalPruning() {
		byte[] summary = summarize("A\ud83d\ude00Z", Locale.ROOT);
		for (String needle : List.of("\ud83d", "\ude00", "a\ud83d", "\ude00z", "x\ud83dy", "\ude00\ud83d")) {
			for (LiteralTextSummary.Operation operation : LiteralTextSummary.Operation.values()) {
				assertThat(query(operation, needle).mayMatch(summary, 0)).as("%s, %s", operation, needle).isTrue();
			}
		}
	}

	@Test
	void indexesThePersistedUtf8DecodingRatherThanAnEarlierJavaLabel() {
		byte[] persisted = "A\ud83dZ".getBytes(StandardCharsets.UTF_8);
		String normalized = new String(persisted, StandardCharsets.UTF_8).toLowerCase(Locale.ROOT);
		byte[] framed = new byte[persisted.length + 6];
		Arrays.fill(framed, (byte) 'x');
		System.arraycopy(persisted, 0, framed, 3, persisted.length);
		byte[] summary = LiteralTextSummary.create(framed, 3, persisted.length, Locale.ROOT);
		assertThat(query(LiteralTextSummary.Operation.EQUALS, normalized).mayMatch(summary, 0)).isTrue();
		assertThat(summary)
				.isEqualTo(LiteralTextSummary.create(new String(persisted, StandardCharsets.UTF_8), Locale.ROOT));
	}

	@Test
	void probesDirectBuffersAtOffsetsWithoutDependingOnByteOrderOrChangingPosition() {
		byte[] summary = summarize("A long enough NEEDLE label", Locale.ROOT);
		byte[] framed = new byte[summary.length + 11];
		System.arraycopy(summary, 0, framed, 5, summary.length);
		ByteBuffer nativeSummary = ByteBuffer.allocateDirect(framed.length).order(ByteOrder.LITTLE_ENDIAN);
		nativeSummary.put(framed).position(2);
		ByteBuffer readOnly = nativeSummary.asReadOnlyBuffer().order(ByteOrder.LITTLE_ENDIAN);
		for (String needle : List.of("needle", "xylophone")) {
			LiteralTextSummary.Query query = query(LiteralTextSummary.Operation.CONTAINS, needle);
			boolean expected = query.mayMatch(summary, 0);
			assertThat(query.mayMatch(framed, 5)).isEqualTo(expected);
			assertThat(query.mayMatch(nativeSummary, 5)).isEqualTo(expected);
			assertThat(query.mayMatch(readOnly, 5)).isEqualTo(expected);
		}
		assertThat(nativeSummary.position()).isEqualTo(2);
		assertThat(readOnly.position()).isEqualTo(2);
		assertThat(nativeSummary.order()).isEqualTo(ByteOrder.LITTLE_ENDIAN);
	}

	@Test
	void missingTruncatedOrUnknownMetadataCannotRejectValues() {
		LiteralTextSummary.Query query = query(LiteralTextSummary.Operation.EQUALS, "missing needle");
		byte[] summary = summarize("unrelated", Locale.ROOT);
		assertThat(query.mayMatch((byte[]) null, 0)).isTrue();
		assertThat(query.mayMatch((ByteBuffer) null, 0)).isTrue();
		assertThat(query.mayMatch(summary, -1)).isTrue();
		assertThat(query.mayMatch(summary, 1)).isTrue();
		assertThat(query.mayMatch(Arrays.copyOf(summary, summary.length - 1), 0)).isTrue();
		assertThat(query.mayMatch(ByteBuffer.wrap(summary).limit(summary.length - 1), 0)).isTrue();
		for (int offset : new int[] { 0, 2, 3 }) {
			byte[] unknown = summary.clone();
			unknown[offset] ^= (byte) 0x80;
			assertThat(query.mayMatch(unknown, 0)).isTrue();
			assertThat(query.mayMatch(ByteBuffer.wrap(unknown), 0)).isTrue();
		}
	}

	@Test
	void aLongSaturatedLabelStillRetainsMatchesAtItsEnd() {
		Random random = new Random(0x51a7eL);
		StringBuilder label = new StringBuilder(32_768);
		for (int i = 0; i < 32_000; i++) {
			label.append((char) (' ' + random.nextInt(95)));
		}
		label.append("FINAL-\u03a3-NEEDLE-\ud83d\ude00");
		String normalized = label.toString().toLowerCase(Locale.ROOT);
		byte[] summary = summarize(label.toString(), Locale.ROOT);
		assertThat(query(LiteralTextSummary.Operation.EQUALS, normalized).mayMatch(summary, 0)).isTrue();
		assertThat(query(LiteralTextSummary.Operation.CONTAINS, normalized.substring(normalized.length() - 18))
				.mayMatch(summary, 0)).isTrue();
	}

	@Test
	void randomizedUnicodeMatchesAreNeverRejected() {
		Random random = new Random(0x1e771eL);
		int[] alphabet = { 'A', 'a', 'I', 'i', '\u0130', '\u0131', '\u03a3', '\u03c2', '\u0301', '\u0307',
				' ', 0, '\u00c5', '\u00df', 0x1f600, 0x10400, 0x4e2d };
		for (Locale locale : List.of(Locale.ROOT, Locale.forLanguageTag("tr"), Locale.forLanguageTag("lt"))) {
			for (int sample = 0; sample < 150; sample++) {
				StringBuilder label = new StringBuilder();
				int length = random.nextInt(24);
				for (int i = 0; i < length; i++) {
					label.appendCodePoint(alphabet[random.nextInt(alphabet.length)]);
				}
				String normalized = label.toString().toLowerCase(locale);
				byte[] summary = summarize(label.toString(), locale);
				assertThat(LiteralTextSummary.prepare(LiteralTextSummary.Operation.EQUALS, normalized, locale)
						.mayMatch(summary, 0)).isTrue();
				assertEverySubstringSurvives(summary, normalized, locale);
			}
		}
	}

	private static void assertEverySubstringSurvives(byte[] summary, String normalized, Locale locale) {
		for (int start = 0; start <= normalized.length(); start++) {
			for (int end = start; end <= normalized.length(); end++) {
				String needle = normalized.substring(start, end);
				assertThat(LiteralTextSummary.prepare(LiteralTextSummary.Operation.CONTAINS, needle, locale)
						.mayMatch(summary, 0)).as("substring [%s,%s] of %s under %s", start, end, normalized, locale)
								.isTrue();
				if (start == 0) {
					assertThat(LiteralTextSummary.prepare(LiteralTextSummary.Operation.STARTS_WITH, needle, locale)
							.mayMatch(summary, 0)).isTrue();
				}
			}
		}
	}

	private static byte[] summarize(String label, Locale locale) {
		byte[] utf8 = label.getBytes(StandardCharsets.UTF_8);
		return LiteralTextSummary.create(utf8, 0, utf8.length, locale);
	}

	private static LiteralTextSummary.Query query(LiteralTextSummary.Operation operation, String evaluatedNeedle) {
		return LiteralTextSummary.prepare(operation, evaluatedNeedle, Locale.ROOT);
	}
}
